/**
 * Host-only access to untrusted MCP diagnostics, separate from model-facing
 * errors. Merely logging or JSON-encoding an event cannot expose its detail.
 *
 * @since 1.0.0-rc.0
 */
import * as Layer from "effect/Layer";
import * as runtime from "vibelang-runtime";
/**
 * Optional diagnostic observer, captured when a connection is opened. The
 * synchronous callback must not block; throws are isolated from the protocol.
 * Absent this service, raw diagnostics are discarded, not logged implicitly.
 *
 * @category services
 * @since 1.0.0-rc.0
 */
export class Diagnostics extends runtime.$service("@smthrs/mcp/Diagnostics") {
}
/**
 * Installs a trusted host observer. Inspecting detail requires an explicit
 * `Redacted.value` call and responsibility for its destination and retention.
 *
 * @category layers
 * @since 1.0.0-rc.0
 */
export const layer = (report) => Layer.succeed(Diagnostics)({ report });

/**
 * Internal optional-observer capture. Every detail is redacted with
 * `Redaction.redactDiagnostic` and then wrapped in `Redacted`. Stderr is redacted by the
 * transport, one whole line at a time, before its byte cap.
 *
 * @since 1.0.0-rc.0
 */
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Redacted from "effect/Redacted";
import * as Redaction from "@smthrs/journal/Redaction";
import * as Diagnostics from "../Diagnostics.js";
/**
 * Captures the optional host observer without introducing a required service.
 *
 * @category constructors
 * @since 1.0.0-rc.0
 */
export const make = (server) => Effect.map(Effect.serviceOption(Diagnostics.Diagnostics), (observer) => (source, detail) => {
    if (Option.isNone(observer))
        return;
    try {
        // A remote error can echo a credential and an argument snapshot can
        // carry one under a secret key, so every source is redacted here.
        // StdioTransport redacts stderr line by line as it arrives, holding a
        // value that spans lines until it closes, and caps only the redacted
        // text to `maxStderrBytes`, so the cap cannot cut a credential's
        // recognizable prefix. Redacting that capped tail again would regrow
        // it past the cap.
        const redacted = source === "stderr" ? detail : Redaction.redactDiagnostic(detail);
        const text = typeof redacted === "string" ? redacted : JSON.stringify(redacted);
        const bytes = new TextEncoder().encode(text);
        const truncated = bytes.byteLength > 16_384;
        observer.value.report({
            server,
            source,
            detail: Redacted.make(new TextDecoder().decode(bytes.subarray(0, 16_384), { stream: truncated })),
            truncated,
        });
    }
    catch {
        // Observer failures are not MCP failures. Their messages can themselves
        // contain the diagnostic, so neither attach nor log the thrown value.
    }
});

/**
 * Positive-integer option bounds shared by the transport and the client.
 *
 * Both `connect` functions resolve their defaults and then reject the first
 * option that is not a positive safe integer, before any process is spawned.
 * The check and its error prose live here so the two option lists cannot
 * drift in wording or in semantics.
 *
 * @since 1.0.0-rc.0
 */
import * as Effect from "effect/Effect";
import { McpError } from "../McpError.js";
/**
 * Builds the `protocol_error` failure both modules report for malformed
 * options and frames.
 *
 * @category errors
 * @since 1.0.0-rc.0
 */
export const protocolError = (server, message) => new McpError({ code: "protocol_error", message, server });
/**
 * Whether a value is a positive safe integer.
 *
 * @category validation
 * @since 1.0.0-rc.0
 */
export const isPositiveInteger = (value) => Number.isSafeInteger(value) && value > 0;
/**
 * Fails with `protocol_error` naming the first option whose resolved value is
 * not a positive safe integer. Entries are checked in the order given.
 *
 * @category validation
 * @since 1.0.0-rc.0
 */
export const checkPositiveIntegers = (server, entries) => {
    const invalid = entries.find(([, value]) => !isPositiveInteger(value));
    return invalid === undefined
        ? Effect.void
        : Effect.fail(protocolError(server, `MCP option "${invalid[0]}" must be a positive integer`));
};

/**
 * The request/notify surface both MCP transports provide, and the failure
 * wording they share. {@link McpClient} speaks to this interface only; stdio
 * and Streamable HTTP differ in how a frame travels, not in what it means.
 *
 * @since 1.0.0-rc.1
 */
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import { McpError } from "../McpError.js";
import * as Limits from "./Limits.js";
/**
 * Default request deadline.
 *
 * @category constants
 * @since 1.0.0-rc.0
 */
export const defaultRequestTimeoutMs = 120_000;
/**
 * Default maximum inbound JSON-RPC frame size (one MiB).
 *
 * @category constants
 * @since 1.0.0-rc.0
 */
export const defaultMaxFrameBytes = 1024 * 1024;
/**
 * Default maximum outbound JSON-RPC frame size (one MiB).
 *
 * @category constants
 * @since 1.0.0-rc.0
 */
export const defaultMaxOutboundFrameBytes = 1024 * 1024;
/**
 * The reason sent with a best-effort `notifications/cancelled`.
 *
 * @category constants
 * @since 1.0.0-rc.1
 */
export const cancellationReason = "request no longer awaited";
/**
 * A `connection_closed` failure naming the server.
 *
 * @category errors
 * @since 1.0.0-rc.1
 */
export const closed = (server, reason) => new McpError({ code: "connection_closed", message: `MCP server "${server}" ${reason}`, server });
/**
 * A `timeout` failure naming the server, method and deadline.
 *
 * @category errors
 * @since 1.0.0-rc.1
 */
export const timeout = (server, method, timeoutMs) => new McpError({
    code: "timeout",
    message: `MCP server "${server}" did not answer ${method} within ${timeoutMs}ms`,
    server
});
/**
 * The model-facing failure for a correlated JSON-RPC error reply. Remote text
 * is withheld; the caller reports it to Diagnostics.
 *
 * @category errors
 * @since 1.0.0-rc.1
 */
export const replyError = (server, method, reply) => {
    // Servers do not standardize unknown-tool prose, so this heuristic stays
    // limited to the two MCP error codes and an explicit tool plus absence phrase.
    const remoteUnknownTool = (reply.code === -32_601 || reply.code === -32_602) &&
        /\btool\b/i.test(reply.message) &&
        /\b(?:unknown|unrecognized|no such|not found)\b/i.test(reply.message);
    return new McpError({
        code: method === "tools/call"
            ? remoteUnknownTool ? "tool_not_found" : "tool_failed"
            : "protocol_error",
        message: `MCP server "${server}" failed ${method} (${reply.code}); remote details withheld`,
        server
    });
};
/**
 * Splits a byte stream into lines in linear time, retaining one bounded
 * partial line. Lines end at LF, with a CR before the LF dropped; with
 * `crTerminates`, as server-sent events require, a lone CR also ends a line.
 * Blank lines are kept: server-sent events use them as delimiters.
 *
 * @category constructors
 * @since 1.0.0-rc.1
 */
export const lines = (server, maxLineBytes, stream, options = {}) => {
    const crTerminates = options.crTerminates === true;
    const decoder = new TextDecoder();
    const decode = (partial) => {
        const joined = new Uint8Array(partial.bytes);
        let offset = 0;
        for (const piece of partial.pieces) {
            joined.set(piece, offset);
            offset += piece.byteLength;
        }
        const end = joined[partial.bytes - 1] === 0x0d ? partial.bytes - 1 : partial.bytes;
        return decoder.decode(joined.subarray(0, end));
    };
    const terminator = (chunk, from) => {
        if (!crTerminates)
            return chunk.indexOf(0x0a, from);
        for (let index = from; index < chunk.byteLength; index += 1) {
            if (chunk[index] === 0x0a || chunk[index] === 0x0d)
                return index;
        }
        return -1;
    };
    const tooLong = () => Effect.fail(Limits.protocolError(server, `MCP frame exceeded ${maxLineBytes} bytes`));
    return stream.pipe(Stream.mapAccumEffect(() => ({ pieces: [], bytes: 0, skipLf: false }), (partial, chunk) => {
        const complete = [];
        const append = (piece) => {
            if (piece.byteLength === 0)
                return true;
            const bytes = partial.bytes + piece.byteLength;
            // A final CR may be the first half of CRLF. Allow that one byte
            // beyond the cap, but count it if more frame content follows.
            const contentBytes = bytes - (piece[piece.byteLength - 1] === 0x0d ? 1 : 0);
            if (contentBytes > maxLineBytes)
                return false;
            partial.pieces.push(piece);
            partial.bytes = bytes;
            return true;
        };
        // The LF of a CRLF split across chunks ends nothing new.
        let start = partial.skipLf && chunk[0] === 0x0a ? 1 : 0;
        partial.skipLf = false;
        for (let end = terminator(chunk, start); end !== -1; end = terminator(chunk, start)) {
            if (!append(chunk.subarray(start, end)))
                return tooLong();
            complete.push(decode(partial));
            partial = { pieces: [], bytes: 0, skipLf: false };
            start = end + 1;
            if (chunk[end] === 0x0d) {
                if (start === chunk.byteLength)
                    partial.skipLf = true;
                else if (chunk[start] === 0x0a)
                    start += 1;
            }
        }
        if (!append(chunk.subarray(start)))
            return tooLong();
        return Effect.succeed([partial, complete]);
    }, { onHalt: (partial) => partial.bytes === 0 ? [] : [decode(partial)] }));
};

/**
 * Projects a connected MCP server's tools as an ordinary {@link FlowBinding.Source}.
 *
 * This is the whole adapter: `@smthrs/harness/FlowBinding`'s own module doc
 * already names the target directly: "a standard filesystem flow, a memory
 * flow, an incoming MCP tool, a durable child agent" are all just a flow
 * declaration plus the code that runs it. Nothing about the harness, the
 * registry, or the cell loop needs to know a given flow's implementation
 * happens to proxy a remote MCP `tools/call`; a cell that reads a file and a
 * cell that calls an MCP tool run the identical two lines.
 *
 * @since 1.0.0-rc.0
 */
import * as Exit from "effect/Exit";
import * as Effect_1 from "effect/Effect";
import * as Capability from "@smthrs/capability/Capability";
import * as Effects from "@smthrs/core/Effects";
import * as FlowBinding from "@smthrs/harness/FlowBinding";
import { Effect, Schema, Scope } from "effect";
import * as McpClient from "./McpClient.js";
import { McpError } from "./McpError.js";
/**
 * Decoded input accepted by every MCP tool flow, which is whatever the remote
 * tool's own JSON Schema describes. The registry still discloses the real parameter
 * shape, as shown by {@link toolBinding}. This is only the runtime decode, and it
 * is permissive because the server, not this adapter, owns validation.
 *
 * @category schemas
 * @since 1.0.0-rc.0
 */
export const Args = Schema.Record(Schema.String, Schema.Unknown);
/**
 * Decoded output returned by every MCP tool flow, carrying the tool's content
 * blocks by shape plus whether the server reported an error.
 *
 * @category schemas
 * @since 1.0.0-rc.0
 */
export const Result = Schema.Struct({
    content: Schema.Array(Schema.Record(Schema.String, Schema.Unknown)),
    isError: Schema.Boolean,
    structuredContent: Schema.optional(Schema.Record(Schema.String, Schema.Unknown))
});
/**
 * The authority every MCP tool flow declares.
 *
 * An MCP tool is opaque code this adapter does not control, the same
 * situation `@smthrs/registry/MarkdownFlow` calls "unprojectable authority"
 * for a skill with no declared `capabilities`: the honest declaration is
 * everything, not a guess.
 *
 * It is spelled as one exact `namespace:operation:resource` per action because
 * the cell boundary reads each declaration with `Capability.parse`, which
 * rejects anything that does not have exactly those three colon-separated
 * components. An unparseable declaration counts as unauthorized. The list is
 * derived from `Capability.Action.literals`, so adding a host action cannot
 * silently omit it from MCP tools, and it is frozen so no caller can narrow
 * or widen what every tool declares. Each binding records it deduplicated and
 * sorted, as `FlowBinding.make` records every declaration.
 *
 * @category constants
 * @since 1.0.0-rc.0
 */
export const capabilities = Object.freeze(Capability.Action.literals.map((action) => `${action}:**`));
/**
 * The conservative effect envelope every MCP tool flow declares.
 *
 * @category effects
 * @since 1.0.0-rc.0
 */
export const effects = Effects.make({
    reads: ["**"],
    writes: ["**"],
    mode: "expected",
    onConflict: "serialize",
    tier: "irreversible"
});
/** One remote tool, bound to a flow name scoped by server so two servers may reuse a tool name. */
const toolBinding = (client, tool, prefix) => {
    const toolName = tool.name;
    return FlowBinding.make({
        flow: {
            name: `${prefix}/${toolName}`,
            // The server authors this text, so it is attributed as remote content
            // rather than read as if the host had written it. The client bounds it.
            description: tool.description === undefined
                ? `MCP tool "${toolName}" on server "${client.server}"`
                : `MCP tool "${toolName}" on server "${client.server}". Server-supplied description: ${tool.description}`,
            capabilities,
            effects,
            input: Args,
            output: Result
        },
        // The server's own JSON Schema document, carried by value so a caller
        // reading `ctx.flows` sees the real parameter shape rather than `Args`'s
        // permissive record type.
        inputDocument: tool.inputSchema,
        // McpClient authors these messages with remote/process diagnostics withheld.
        publicError: (error) => error.message,
        handler: (input) => Effect.map(client.callTool(toolName, input), (result) => result.structuredContent === undefined
            ? { content: result.content, isError: result.isError }
            : {
                content: result.content,
                isError: result.isError,
                structuredContent: result.structuredContent
            })
    });
};
/**
 * Projects an already-connected MCP session's tool catalog as a
 * {@link FlowBinding.Source}, one flow per tool.
 *
 * The client is a precondition, not a parameter this constructor resolves:
 * connecting is a scoped effect (it owns a subprocess), and a `Source` is not
 * scoped, so the host composes {@link McpClient.connect} once, at the same
 * place it composes every other scoped kernel service, and passes the live
 * client here.
 *
 * This constructor is total: it applies exact filters to the catalog it is
 * given. Use {@link connected} when unknown `include` names and an empty
 * `namePrefix` must fail loudly against a freshly fetched catalog.
 *
 * @category constructors
 * @since 1.0.0-rc.0
 */
export const mcp = (client, options = {}) => {
    const prefix = options.namePrefix ?? `mcp/${client.server}`;
    const include = options.include === undefined || options.include.length === 0
        ? undefined
        : new Set(options.include);
    const exclude = new Set(options.exclude ?? []);
    const tools = client.tools.filter((tool) => (include === undefined || include.has(tool.name)) && !exclude.has(tool.name));
    return FlowBinding.source(prefix, tools.map((tool) => toolBinding(client, tool, prefix)));
};
/**
 * Connects to an MCP server and projects its tools in one step.
 *
 * This is the checked entry point: it validates projection options against
 * the freshly fetched catalog before constructing the source. An empty prefix
 * fails before spawning. Failed or interrupted setup, including projection
 * validation, releases the connection before returning to the caller.
 *
 * @category constructors
 * @since 1.0.0-rc.0
 */
export const connected = Effect_1.fnUntraced(function* connected(options) {
    if (options.namePrefix === "") {
        return yield* Effect_1.fail(new McpError({
            code: "protocol_error",
            message: `MCP server "${options.server}" option "namePrefix" must not be empty`,
            server: options.server
        }));
    }
    return yield* Effect.acquireUseRelease(Effect.flatMap(Effect.scope, Scope.fork), (scope) => Scope.provide((Effect_1.gen(function* () {
        const client = yield* McpClient.connect(options);
        const offered = new Set(client.tools.map((tool) => tool.name));
        const missing = options.include?.find((name) => !offered.has(name));
        if (missing !== undefined) {
            return yield* Effect_1.fail(new McpError({
                code: "tool_not_found",
                message: `MCP server "${client.server}" offers no requested include tool`,
                server: client.server
            }));
        }
        return mcp(client, options);
    })), scope), 
    // Projection rejection must release the successfully initialized client.
    (scope, exit) => Exit.isFailure(exit) ? Scope.close(scope, exit) : Effect.void);
});
